export const sources = {
  "src/components/GenerateVoiceModal/GenerateVoiceModal.jsx": "import { useMessageLanguage } from '../../i18n/useMessageLanguage.js';\nimport {presentTechnicalMessage, presentStoredError } from '../../i18n/userMessage.js';\nimport { useEffect, useMemo, useState } from 'react';\nimport { invoke } from '@tauri-apps/api/core';\nimport { listen } from '@tauri-apps/api/event';\nimport { useEscapeKey } from '../../hooks/useEscapeKey';\nimport { KEYS, read, write } from '../../store/persistentSettings';\nimport {\n  PIPER_DEFAULT_LANGUAGE,\n  PIPER_DEFAULT_VOICE,\n  PIPER_LANGUAGE_OPTIONS,\n  piperDefaultVoiceForLanguage,\n} from '../../store/xttsSettings';\nimport { formatFrenchCount } from '../../utils/frenchText.js';\nimport { Button } from '../common/Button';\nimport { releaseTauriListener } from '../../utils/tauriListener';\nimport './GenerateVoiceModal.css';\n\nconst LANGUAGE_OPTIONS = [\n  { value: 'fr', label: 'Français' },\n  { value: 'en', label: 'English' },\n  { value: 'es', label: 'Español' },\n  { value: 'de', label: 'Deutsch' },\n  { value: 'it', label: 'Italiano' },\n  { value: 'pt', label: 'Português' },\n];\n\nconst PIPER_MAX_TEXT_CHARS = 5000;\n\nexport function GenerateVoiceModal(props) {\n  const isPiper = (props.xttsSettings?.backend || 'piper') === 'piper';\n  return isPiper ? <PiperVoiceModal {...props} /> : <XttsVoiceModal {...props} />;\n}\n\n// ── Châssis partagé ──────────────────────────────────────────────────────────\n\nfunction VoiceModalShell({\n  badges,\n  text,\n  setText,\n  initialText,\n  submitting,\n  statusMessage,\n  error,\n  footerLeft,\n  footerActions,\n  contextSub,\n  label,\n  onClose,\n  children,\n}) {\n  const textLength = text.trim().length;\n  return (\n    <div className=\"modal-overlay\">\n      <div className=\"modal-box tts-modal\" onClick={(e) => e.stopPropagation()}>\n        <div className=\"modal-header\">\n          <span>Générer une voix</span>\n          <Button variant=\"icon\" className=\"modal-close\" onClick={onClose} disabled={submitting}>×</Button>\n        </div>\n\n        <div className=\"tts-body\">\n          <div className=\"tts-hero\">\n            <div className=\"tts-hero-main\">\n              <div className=\"tts-context-label\">{label}</div>\n              <div className=\"tts-context-sub\">{contextSub}</div>\n            </div>\n            <div className=\"tts-badges\">{badges}</div>\n          </div>\n\n          <label className=\"tts-field\">\n            <span>Texte à lire</span>\n            <textarea\n              className=\"tts-textarea\"\n              value={text}\n              onChange={(e) => setText(e.target.value)}\n              placeholder=\"Tape ici le texte à transformer en voix…\"\n              disabled={submitting}\n            />\n            <div className=\"tts-field-row\">\n              <span className=\"tts-helper\">\n                {initialText ? 'Le texte est prérempli d’après le champ audio actuel.' : 'Saisis le texte exact à lire par la voix.'}\n              </span>\n              <span className=\"tts-count\">\n                {formatFrenchCount(textLength, 'caractère', 'caractères')}\n              </span>\n            </div>\n          </label>\n\n          {children}\n\n          {statusMessage && <div className=\"tts-status\">{presentTechnicalMessage(statusMessage)}</div>}\n          {error && <div className=\"tts-error\">{presentStoredError(error)}</div>}\n        </div>\n\n        <div className=\"tts-footer\">\n          {footerLeft || <span />}\n          <div className=\"tts-footer-actions\">{footerActions}</div>\n        </div>\n      </div>\n    </div>\n  );\n}\n\n// ── Backend Piper (défaut, zéro-config) ──────────────────────────────────────\n\nfunction PiperVoiceModal({\n  savePath,\n  xttsSettings,\n  label,\n  initialText = '',\n  filenameHint = 'tts',\n  target = null,\n  onUpdateXttsSettings,\n  onQueueGenerate,\n  onClose,\n}) {\n  const [text, setText] = useState(initialText);\n  const [voices, setVoices] = useState([]);\n  const [binaryInstalled, setBinaryInstalled] = useState(false);\n  const [selectedLanguage, setSelectedLanguage] = useState(\n    xttsSettings.piperLanguage || PIPER_DEFAULT_LANGUAGE,\n  );\n  const [selectedVoice, setSelectedVoice] = useState(() => (\n    xttsSettings.piperVoice || read(KEYS.PIPER_LAST_VOICE) || PIPER_DEFAULT_VOICE\n  ));\n  const [speed, setSpeed] = useState(() => {\n    const value = Number(xttsSettings.piperSpeed);\n    return Number.isFinite(value) && value > 0 ? value : 1.0;\n  });\n  const [submitting, setSubmitting] = useState(false);\n  const [error, setError] = useState('');\n  useMessageLanguage();\n  const [statusMessage, setStatusMessage] = useState('Voix prête à l’emploi, sans configuration.');\n\n  const selectedVoiceInfo = useMemo(\n    () => voices.find((voice) => voice.id === selectedVoice) || null,\n    [voices, selectedVoice],\n  );\n  const visibleVoices = useMemo(\n    () => voices.filter((voice) => voice.language === selectedLanguage),\n    [voices, selectedLanguage],\n  );\n  const needsProvision = !binaryInstalled || (selectedVoiceInfo ? !selectedVoiceInfo.installed : true);\n\n  // reason: chargement one-shot du catalogue de voix Piper au montage.\n  // eslint-disable-next-line react-hooks/exhaustive-deps\n  useEffect(() => {\n    let cancelled = false;\n    invoke('piper_list_voices')\n      .then((status) => {\n        if (cancelled) return;\n        const list = status?.voices || [];\n        setVoices(list);\n        setBinaryInstalled(!!status?.binaryInstalled);\n        const currentVoice = list.find((voice) => voice.id === selectedVoice);\n        const language = currentVoice?.language\n          || xttsSettings.piperLanguage\n          || status?.defaultLanguage\n          || PIPER_DEFAULT_LANGUAGE;\n        setSelectedLanguage(language);\n        setSelectedVoice(currentVoice?.language === language\n          ? currentVoice.id\n          : piperDefaultVoiceForLanguage(list, language));\n      })\n      .catch((e) => {\n        if (!cancelled) setError(e);\n      });\n    return () => { cancelled = true; };\n  }, []);\n\n  // Pendant le provisionnement, refléter les messages discrets émis par le backend.\n  useEffect(() => {\n    if (!submitting) return undefined;\n    let unlisten = null;\n    let cancelled = false;\n    listen('piper-log', (event) => {\n      if (!cancelled) setStatusMessage(event.payload);\n    }).then((fn) => {\n      if (cancelled) releaseTauriListener(fn);\n      else unlisten = fn;\n    }).catch(() => {});\n    return () => { cancelled = true; releaseTauriListener(unlisten); };\n  }, [submitting]);\n\n  useEscapeKey(true, () => { if (!submitting) onClose?.(); });\n\n  async function handleGenerate() {\n    if (!text.trim()) { setError('Le texte à générer est vide.'); return; }\n    if (text.trim().length > PIPER_MAX_TEXT_CHARS) {\n      setError(`Le texte est trop long pour Piper (${text.trim().length} caractères, maximum ${PIPER_MAX_TEXT_CHARS}).`);\n      return;\n    }\n    if (!selectedVoice) { setError('Choisis une voix.'); return; }\n\n    setSubmitting(true);\n    setError('');\n    try {\n      // Provision (téléchargement unique) AVANT la mise en file, pour donner un\n      // feedback discret « Préparation de la voix… » au 1er usage. Idempotent :\n      // sans effet si déjà installé.\n      if (needsProvision) {\n        setStatusMessage('Préparation de la voix… (téléchargement unique)');\n        await invoke('piper_ensure_voice', { voice: selectedVoice });\n        setBinaryInstalled(true);\n        setVoices((prev) => prev.map((voice) => (\n          voice.id === selectedVoice ? { ...voice, installed: true } : voice\n        )));\n      }\n      await onQueueGenerate?.({\n        target,\n        targetLabel: label,\n        voiceLabel: selectedVoiceInfo?.label || selectedVoice,\n        request: { text, voice: selectedVoice, speed, savePath, filenameHint },\n      });\n      write(KEYS.PIPER_LAST_VOICE, selectedVoice);\n      onUpdateXttsSettings?.({\n        piperLanguage: selectedLanguage,\n        piperVoice: selectedVoice,\n        piperSpeed: speed,\n      });\n      onClose();\n    } catch (e) {\n      setError({ userMessage: e, suffix: \"\\nRéessaie, ou passe à XTTS dans les Préférences si le problème persiste.\" });\n      setStatusMessage('');\n    } finally {\n      setSubmitting(false);\n    }\n  }\n\n  const badges = <span className=\"tts-badge gpu\">Piper</span>;\n\n  return (\n    <VoiceModalShell\n      badges={badges}\n      text={text}\n      setText={setText}\n      initialText={initialText}\n      submitting={submitting}\n      statusMessage={statusMessage}\n      error={presentStoredError(error)}\n      label={label}\n      contextSub={<>Le fichier sera stocké dans <strong>voix-générées/</strong> dans l’emplacement de travail.</>}\n      onClose={onClose}\n      footerActions={(\n        <Button variant=\"primary-violet\" onClick={handleGenerate} disabled={submitting || voices.length === 0}>\n          {submitting ? (needsProvision ? 'Préparation…' : 'Ajout…') : 'Générer'}\n        </Button>\n      )}\n    >\n      <div className=\"tts-grid\">\n        <label className=\"tts-field\">\n          <span>Langue</span>\n          <select\n            className=\"tts-input\"\n            value={selectedLanguage}\n            onChange={(e) => {\n              const language = e.target.value;\n              const voice = piperDefaultVoiceForLanguage(voices, language);\n              setSelectedLanguage(language);\n              setSelectedVoice(voice);\n              write(KEYS.PIPER_LAST_VOICE, voice);\n              onUpdateXttsSettings?.({ piperLanguage: language, piperVoice: voice });\n            }}\n            disabled={submitting || voices.length === 0}\n          >\n            {PIPER_LANGUAGE_OPTIONS.map(({ value, label: optionLabel }) => (\n              <option key={value} value={value}>{optionLabel}</option>\n            ))}\n          </select>\n        </label>\n\n        <label className=\"tts-field\">\n          <span>Voix</span>\n          <select\n            className=\"tts-input\"\n            value={selectedVoice}\n            onChange={(e) => {\n              setSelectedVoice(e.target.value);\n              write(KEYS.PIPER_LAST_VOICE, e.target.value);\n              onUpdateXttsSettings?.({\n                piperLanguage: selectedLanguage,\n                piperVoice: e.target.value,\n              });\n            }}\n            disabled={submitting || visibleVoices.length === 0}\n          >\n            {visibleVoices.length === 0 && <option value=\"\">Chargement des voix…</option>}\n            {visibleVoices.map((voice) => (\n              <option key={voice.id} value={voice.id}>\n                {voice.label}{voice.installed ? '' : ' — à télécharger'}\n              </option>\n            ))}\n          </select>\n        </label>\n\n        <label className=\"tts-field\">\n          <span>Vitesse · {speed.toFixed(2)}×</span>\n          <input\n            className=\"tts-input\"\n            type=\"range\"\n            min=\"0.5\"\n            max=\"1.5\"\n            step=\"0.05\"\n            value={speed}\n            onChange={(e) => setSpeed(Number(e.target.value))}\n            disabled={submitting}\n          />\n        </label>\n      </div>\n      <span className=\"tts-helper\">\n        Piper fonctionne sans serveur ni configuration. La voix est téléchargée automatiquement au premier usage.\n      </span>\n    </VoiceModalShell>\n  );\n}\n\n// ── Backend XTTS (opt-in, avancé) ────────────────────────────────────────────\n\nfunction XttsVoiceModal({\n  savePath,\n  xttsSettings,\n  label,\n  initialText = '',\n  filenameHint = 'tts',\n  target = null,\n  onQueueGenerate,\n  onClose,\n}) {\n  const [text, setText] = useState(initialText);\n  const [language, setLanguage] = useState(xttsSettings.language || 'fr');\n  const [availableVoices, setAvailableVoices] = useState([]);\n  const [selectedVoice, setSelectedVoice] = useState(() => (\n    read(KEYS.XTTS_LAST_VOICE) || read(KEYS.XTTS_LAST_SPEAKER) || ''\n  ));\n  const [loading, setLoading] = useState(true);\n  const [submitting, setSubmitting] = useState(false);\n  const [device, setDevice] = useState(null);\n  useMessageLanguage();\n  const [statusMessage, setStatusMessage] = useState('Connexion à XTTS…');\n  const [error, setError] = useState('');\n  const favoriteVoices = Array.isArray(xttsSettings.favoriteVoices) ? xttsSettings.favoriteVoices : [];\n  const visibleVoices = useMemo(() => {\n    const available = availableVoices.filter(Boolean);\n    if (favoriteVoices.length === 0) return available;\n    const favoritesAvailable = favoriteVoices.filter((voice) => available.includes(voice));\n    return favoritesAvailable.length > 0 ? favoritesAvailable : available;\n  }, [availableVoices, favoriteVoices]);\n  const favoritesUnavailable = favoriteVoices.length > 0\n    && availableVoices.length > 0\n    && favoriteVoices.every((voice) => !availableVoices.includes(voice));\n  const selectedVoiceLabel = selectedVoice || 'Aucune voix disponible';\n\n  async function loadStatus() {\n    setLoading(true);\n    setError('');\n    setStatusMessage('Connexion à XTTS…');\n    try {\n      const status = await invoke('xtts_get_status', { settings: xttsSettings });\n      const voices = status.voices || [];\n      const nextVisibleVoices = favoriteVoices.length > 0\n        ? favoriteVoices.filter((voice) => voices.includes(voice))\n        : voices;\n      const fallbackVoices = nextVisibleVoices.length > 0 ? nextVisibleVoices : voices;\n      const lastVoice = read(KEYS.XTTS_LAST_VOICE) || read(KEYS.XTTS_LAST_SPEAKER) || '';\n      setDevice(status.device || null);\n      setAvailableVoices(voices);\n      setSelectedVoice((current) => {\n        if (fallbackVoices.includes(current)) return current;\n        if (fallbackVoices.includes(lastVoice)) return lastVoice;\n        return fallbackVoices[0] || '';\n      });\n      setStatusMessage(voices.length > 0 ? 'XTTS est prêt.' : 'XTTS est prêt, mais aucune voix n’a été retournée.');\n    } catch (e) {\n      setError(e);\n      setStatusMessage('');\n    } finally {\n      setLoading(false);\n    }\n  }\n\n  // reason: chargement one-shot du statut XTTS au montage de la modale.\n  // eslint-disable-next-line react-hooks/exhaustive-deps\n  useEffect(() => {\n    loadStatus();\n  }, []);\n\n  useEscapeKey(true, () => { if (!submitting) onClose?.(); });\n\n  async function handleGenerate() {\n    if (!text.trim()) { setError('Le texte à générer est vide.'); return; }\n    if (!selectedVoice) { setError('Choisis une voix XTTS.'); return; }\n\n    setSubmitting(true);\n    setError('');\n    try {\n      await onQueueGenerate?.({\n        target,\n        targetLabel: label,\n        voiceLabel: selectedVoiceLabel,\n        request: { text, language, speaker: null, voice: selectedVoice, savePath, filenameHint },\n      });\n      write(KEYS.XTTS_LAST_VOICE, selectedVoice);\n      write(KEYS.XTTS_LAST_SPEAKER, selectedVoice);\n      onClose();\n    } catch (e) {\n      setError(e);\n    } finally {\n      setSubmitting(false);\n    }\n  }\n\n  const badges = (\n    <>\n      <span className={`tts-badge ${loading ? '' : device === 'cuda' ? 'gpu' : 'cpu'}`}>\n        {loading ? 'Initialisation…' : device === 'cuda' ? 'GPU CUDA' : device === 'cpu' ? 'CPU' : 'XTTS'}\n      </span>\n      <span className=\"tts-badge\">Voix XTTS</span>\n    </>\n  );\n\n  return (\n    <VoiceModalShell\n      badges={badges}\n      text={text}\n      setText={setText}\n      initialText={initialText}\n      submitting={submitting}\n      statusMessage={statusMessage}\n      error={presentStoredError(error)}\n      label={label}\n      contextSub={<>Le fichier sera stocké dans <strong>voix-générées/</strong> dans l’emplacement de travail.</>}\n      onClose={onClose}\n      footerLeft={(\n        <Button variant=\"secondary-violet\" onClick={loadStatus} disabled={loading || submitting}>\n          Actualiser XTTS\n        </Button>\n      )}\n      footerActions={(\n        <Button\n          variant=\"primary-violet\"\n          onClick={handleGenerate}\n          disabled={loading || submitting || visibleVoices.length === 0}\n        >\n          {submitting ? 'Ajout…' : 'Générer'}\n        </Button>\n      )}\n    >\n      <div className=\"tts-grid\">\n        <label className=\"tts-field\">\n          <span>Langue</span>\n          <select\n            className=\"tts-input\"\n            value={language}\n            onChange={(e) => setLanguage(e.target.value)}\n            disabled={submitting}\n          >\n            {LANGUAGE_OPTIONS.map(({ value, label: optionLabel }) => (\n              <option key={value} value={value}>{optionLabel}</option>\n            ))}\n          </select>\n        </label>\n\n        <div className=\"tts-field\">\n          <span>Voix sélectionnée</span>\n          <div className=\"tts-device\">{selectedVoiceLabel}</div>\n        </div>\n      </div>\n\n      <label className=\"tts-field\">\n        <span>Voix</span>\n        <select\n          className=\"tts-input\"\n          value={selectedVoice}\n          onChange={(e) => {\n            setSelectedVoice(e.target.value);\n            write(KEYS.XTTS_LAST_VOICE, e.target.value);\n            write(KEYS.XTTS_LAST_SPEAKER, e.target.value);\n          }}\n          disabled={submitting || visibleVoices.length === 0}\n        >\n          {visibleVoices.length === 0 && <option value=\"\">Aucune voix détectée par XTTS</option>}\n          {visibleVoices.map((voiceName) => (\n            <option key={voiceName} value={voiceName}>{voiceName}</option>\n          ))}\n        </select>\n        <span className=\"tts-helper\">\n          {favoriteVoices.length > 0 && !favoritesUnavailable\n            ? 'Liste limitée aux voix favorites configurées dans les préférences.'\n            : favoritesUnavailable\n              ? 'Les voix favorites sont indisponibles ; toutes les voix XTTS détectées sont affichées.'\n              : 'Toutes les voix retournées par XTTS sont disponibles. Ajoute des favorites dans les préférences pour réduire cette liste.'}\n        </span>\n      </label>\n    </VoiceModalShell>\n  );\n}\n",
  "src/components/SDGenerateModal/SDGenerateModal.jsx": "import { useTreeTranslation } from \"../../i18n/useTreeTranslation.jsx\";\nimport { presentTree } from \"../../i18n/treePresentation.js\";\nimport {presentStoredError } from '../../i18n/userMessage.js';\nimport { useState, useEffect } from 'react';\nimport { invoke } from '@tauri-apps/api/core';\nimport { pickSdReferenceImage } from '../../hooks/useFileDialog';\nimport { useEscapeKey } from '../../hooks/useEscapeKey';\nimport { Tooltip } from '../common/Tooltip';\nimport { Button } from '../common/Button';\nimport { Dices } from '../icons/LucideLocal';\nimport { basename } from '../../utils/fileUtils';\nimport './SDGenerateModal.css';\n\nfunction randomSeed() {\n  return Math.floor(Math.random() * 0xFFFFFFFF);\n}\n\nconst DEFAULT_PARAMS = {\n  positivePrompt: 'lunii_style, simple illustration, black and white line art, grayscale, children book style, ',\n  negativePrompt: 'color, photo, realistic, watermark, text',\n  seed: randomSeed(),\n  steps: 20,\n  cfg: 2.5,\n  loraStrength: 0.85,\n};\n\nexport function SDGenerateModal({\n  onGenerate,\n  onClose,\n  currentImagePath = null,\n  currentImageLabel = null,\n  rootImagePath = null,\n  initialJob = null,\n}) {\n  const { t } = useTreeTranslation();\n  const [workflows, setWorkflows] = useState([]);\n  const [loadingWorkflows, setLoadingWorkflows] = useState(true);\n  const [selectedId, setSelectedId] = useState(null);\n  const [referenceImagePath, setReferenceImagePath] = useState(null);\n  const [useCurrentImageAsReference, setUseCurrentImageAsReference] = useState(false);\n  const [useRootImageAsReference, setUseRootImageAsReference] = useState(false);\n  const [params, setParams] = useState(DEFAULT_PARAMS);\n  const [variants, setVariants] = useState(1);\n  const [showAdvanced, setShowAdvanced] = useState(false);\n  const [submitting, setSubmitting] = useState(false);\n  const [error, setError] = useState(null);\n\n  useEffect(() => {\n    invoke('comfyui_list_workflows')\n      .then(wfs => {\n        setWorkflows(wfs);\n        const initialWorkflow = initialJob\n          ? wfs.find(wf => wf.id === initialJob.workflowId)\n          : null;\n        const nextWorkflow = initialWorkflow || wfs[0] || null;\n        if (nextWorkflow) {\n          setSelectedId(nextWorkflow.id);\n          if (initialJob?.params) {\n            setParams({\n              ...DEFAULT_PARAMS,\n              ...initialJob.params,\n              seed: randomSeed(),\n              referenceImagePath: undefined,\n            });\n            setReferenceImagePath(initialJob.params.referenceImagePath || null);\n          } else {\n            applyWorkflowDefaults(nextWorkflow);\n          }\n        }\n        if (initialJob && !initialWorkflow) {\n          setError('Le workflow utilisé par cette génération n’est plus disponible.');\n        }\n      })\n      .catch(e => setError(e))\n      .finally(() => setLoadingWorkflows(false));\n  // reason: chargement one-shot des workflows ComfyUI au montage.\n  // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  useEffect(() => {\n    setUseCurrentImageAsReference(false);\n    setUseRootImageAsReference(false);\n    setReferenceImagePath(null);\n  }, [currentImagePath]);\n\n  useEscapeKey(true, () => {\n    if (!submitting) onClose?.();\n  });\n\n  const selected = workflows.find(w => w.id === selectedId) || null;\n  const hasNegativeSlot = selected && 'negative_prompt' in selected.slots;\n  const hasSeedSlot = selected && 'seed' in selected.slots;\n  const hasStepsSlot = selected && 'steps' in selected.slots;\n  const hasCfgSlot = selected && ('cfg' in selected.slots || 'guidance' in selected.slots);\n  const hasLoraSlot = selected && ('lora_strength_model' in selected.slots || 'lora_strength_clip' in selected.slots);\n  const canUseCurrentImage = !!currentImagePath;\n  const canUseRootImage = !!rootImagePath && rootImagePath !== currentImagePath;\n  const effectiveReferenceImagePath = useCurrentImageAsReference\n    ? currentImagePath\n    : useRootImageAsReference\n      ? rootImagePath\n      : referenceImagePath;\n\n  function applyWorkflowDefaults(wf) {\n    const dv = wf?.defaultValues;\n    if (!dv) return;\n    setParams(p => ({\n      ...p,\n      ...(dv.positive_prompt !== undefined && { positivePrompt: dv.positive_prompt }),\n      ...(dv.negative_prompt !== undefined && { negativePrompt: dv.negative_prompt }),\n      // seed intentionally NOT applied from defaults — always keep it random\n      ...(dv.steps !== undefined && { steps: Number(dv.steps) || p.steps }),\n      ...(dv.cfg !== undefined && { cfg: parseFloat(dv.cfg) || p.cfg }),\n      ...(dv.lora_strength_model !== undefined && { loraStrength: parseFloat(dv.lora_strength_model) || p.loraStrength }),\n    }));\n  }\n\n  function handleWorkflowSelect(id) {\n    setParams(p => ({ ...p, seed: randomSeed() }));\n    applyWorkflowDefaults(workflows.find(w => w.id === id));\n    setSelectedId(id);\n    setReferenceImagePath(null);\n    setError(null);\n  }\n\n  async function handlePickReference() {\n    const path = await pickSdReferenceImage();\n    if (path) setReferenceImagePath(path);\n  }\n\n  async function handleSubmit() {\n    if (!selected) return;\n    if (selected.requiresReferenceImage && !effectiveReferenceImagePath) {\n      setError('Une image de référence est requise pour ce workflow.');\n      return;\n    }\n    setSubmitting(true);\n    setError(null);\n    try {\n      for (let i = 0; i < variants; i++) {\n        onGenerate(selected.id, selected.name, {\n          positivePrompt: params.positivePrompt,\n          negativePrompt: params.negativePrompt,\n          seed: params.seed + i,\n          steps: params.steps,\n          cfg: params.cfg,\n          loraStrength: params.loraStrength,\n          referenceImagePath: effectiveReferenceImagePath || null,\n        });\n      }\n      onClose();\n    } catch (e) {\n      setError(e);\n      setSubmitting(false);\n    }\n  }\n\n  const refName = effectiveReferenceImagePath\n    ? basename(effectiveReferenceImagePath)\n    : null;\n\n  return (\n    <div className=\"modal-overlay\">\n      <div className=\"modal-box sd-generate-box\">\n        <div className=\"modal-header\">\n          <span>Générer une image avec ComfyUI</span>\n          <Button variant=\"icon\" className=\"modal-close\" onClick={onClose}>✕</Button>\n        </div>\n\n        <div className=\"sd-generate-body\">\n          {/* Sélecteur de workflow */}\n          <div className=\"sd-section-label\">Workflow</div>\n          {loadingWorkflows ? (\n            <div className=\"sd-loading\">Chargement des workflows…</div>\n          ) : workflows.length === 0 ? (\n            <div className=\"sd-empty\">Aucun workflow disponible.</div>\n          ) : (\n            <div className=\"sd-workflow-cards\">\n              {workflows.map(wf => (\n                <button\n                  key={wf.id}\n                  className={`sd-workflow-card ${selectedId === wf.id ? 'selected' : ''}`}\n                  onClick={() => handleWorkflowSelect(wf.id)}\n                >\n                  <div className=\"sd-workflow-name\">{wf.name}</div>\n                  <div className=\"sd-workflow-desc\">{wf.description}</div>\n                  {wf.requiresReferenceImage && (\n                    <div className=\"sd-workflow-tag\">Image requise</div>\n                  )}\n                </button>\n              ))}\n            </div>\n          )}\n\n          {/* Image de référence */}\n          {selected?.requiresReferenceImage && (\n            <div className=\"sd-field\">\n              <div className=\"sd-section-label\">Image de référence</div>\n              {canUseRootImage && (\n                <label className=\"sd-ref-toggle\">\n                  <input\n                    type=\"checkbox\"\n                    checked={useRootImageAsReference}\n                    onChange={e => {\n                      setUseRootImageAsReference(e.target.checked);\n                      if (e.target.checked) { setUseCurrentImageAsReference(false); setReferenceImagePath(null); }\n                    }}\n                  />\n                  <span>Utiliser l'image de couverture du menu racine</span>\n                </label>\n              )}\n              {canUseCurrentImage && (\n                <label className=\"sd-ref-toggle\">\n                  <input\n                    type=\"checkbox\"\n                    checked={useCurrentImageAsReference}\n                    onChange={e => {\n                      setUseCurrentImageAsReference(e.target.checked);\n                      if (e.target.checked) { setUseRootImageAsReference(false); setReferenceImagePath(null); }\n                    }}\n                  />\n                  <span>{t(\"tree:image.reference.use\", { label: presentTree(currentImageLabel) || t(\"tree:image.reference.field\") })}</span>\n                </label>\n              )}\n              <div className=\"sd-ref-row\">\n                <Button\n                  size=\"sm\"\n                  variant=\"secondary-violet\"\n                  onClick={handlePickReference}\n                  disabled={useCurrentImageAsReference || useRootImageAsReference}\n                >\n                  Choisir une image…\n                </Button>\n                {refName && <span className=\"sd-ref-name\">{refName}</span>}\n              </div>\n            </div>\n          )}\n\n          {/* Prompt positif */}\n          <div className=\"sd-field\">\n            <div className=\"sd-section-label\">Prompt</div>\n            <textarea\n              className=\"sd-textarea\"\n              value={params.positivePrompt}\n              onChange={e => setParams(p => ({ ...p, positivePrompt: e.target.value }))}\n              rows={7}\n              placeholder=\"lunii_style, simple illustration…\"\n            />\n          </div>\n\n          {/* Prompt négatif */}\n          {hasNegativeSlot && (\n            <div className=\"sd-field\">\n              <div className=\"sd-section-label\">Prompt négatif</div>\n              <textarea\n                className=\"sd-textarea\"\n                value={params.negativePrompt}\n                onChange={e => setParams(p => ({ ...p, negativePrompt: e.target.value }))}\n                rows={3}\n                placeholder=\"color, photo, realistic…\"\n              />\n            </div>\n          )}\n\n          {/* Variantes */}\n          <div className=\"sd-field sd-variants-row\">\n            <div className=\"sd-section-label\">Variantes</div>\n            <div className=\"sd-variants-toggle\">\n              {[1, 2].map(n => (\n                <Button\n                  key={n}\n                  size=\"sm\"\n                  variant={variants === n ? 'secondary-violet' : 'secondary'}\n                  onClick={() => setVariants(n)}\n                >\n                  {n}\n                </Button>\n              ))}\n            </div>\n          </div>\n\n          {/* Section avancée */}\n          {(hasSeedSlot || hasStepsSlot || hasCfgSlot || hasLoraSlot) && (\n            <div className=\"sd-advanced\">\n              <button\n                className=\"sd-advanced-toggle\"\n                onClick={() => setShowAdvanced(v => !v)}\n              >\n                {showAdvanced ? '▾' : '▸'} Paramètres avancés\n              </button>\n              {showAdvanced && (\n                <div className=\"sd-advanced-body\">\n                  {hasSeedSlot && (\n                    <div className=\"sd-param-row\">\n                      <label className=\"sd-param-label\">Seed</label>\n                      <div style={{ display: 'flex', gap: 4, alignItems: 'center' }}>\n                        <input\n                          type=\"number\"\n                          className=\"sd-seed-input\"\n                          value={params.seed}\n                          onChange={e => setParams(p => ({ ...p, seed: parseInt(e.target.value, 10) || 0 }))}\n                        />\n                        <Tooltip text=\"Seed aléatoire\">\n                          <Button\n                            size=\"sm\"\n                            variant=\"secondary-violet\"\n                            onClick={() => setParams(p => ({ ...p, seed: randomSeed() }))}\n                          ><Dices style={{ width: 12, height: 12, verticalAlign: '-2px' }} /></Button>\n                        </Tooltip>\n                      </div>\n                    </div>\n                  )}\n                  {hasStepsSlot && (\n                    <div className=\"sd-param-row\">\n                      <label className=\"sd-param-label\">Steps <span className=\"sd-param-value\">{params.steps}</span></label>\n                      <input\n                        type=\"range\" min={1} max={50}\n                        value={params.steps}\n                        onChange={e => setParams(p => ({ ...p, steps: parseInt(e.target.value) }))}\n                        className=\"sd-slider\"\n                      />\n                    </div>\n                  )}\n                  {hasCfgSlot && (\n                    <div className=\"sd-param-row\">\n                      <label className=\"sd-param-label\">CFG <span className=\"sd-param-value\">{params.cfg.toFixed(1)}</span></label>\n                      <input\n                        type=\"range\" min={0.1} max={20} step={0.1}\n                        value={params.cfg}\n                        onChange={e => setParams(p => ({ ...p, cfg: parseFloat(e.target.value) }))}\n                        className=\"sd-slider\"\n                      />\n                    </div>\n                  )}\n                  {hasLoraSlot && (\n                    <div className=\"sd-param-row\">\n                      <label className=\"sd-param-label\">LoRA <span className=\"sd-param-value\">{params.loraStrength.toFixed(2)}</span></label>\n                      <input\n                        type=\"range\" min={0} max={2} step={0.05}\n                        value={params.loraStrength}\n                        onChange={e => setParams(p => ({ ...p, loraStrength: parseFloat(e.target.value) }))}\n                        className=\"sd-slider\"\n                      />\n                    </div>\n                  )}\n                </div>\n              )}\n            </div>\n          )}\n\n          {error && <div className=\"sd-error\">{presentStoredError(error)}</div>}\n        </div>\n\n        <div className=\"modal-footer\">\n          <Button size=\"sm\" onClick={onClose} disabled={submitting}>\n            Annuler\n          </Button>\n          <Button\n            variant=\"primary-violet\"\n            onClick={handleSubmit}\n            disabled={submitting || !selected || loadingWorkflows}\n          >\n            {submitting ? 'Envoi…' : `Générer${variants > 1 ? ` ×${variants}` : ''}`}\n          </Button>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
  "src/components/SDQueuePanel/SDQueuePanel.jsx": "import { presentUserMessage, presentTechnicalMessage } from '../../i18n/userMessage.js';\nimport { useMessageLanguage } from '../../i18n/useMessageLanguage.js';\nimport { getIntlLocale } from '../../i18n/language.js';\nimport { useEffect, useMemo, useRef, useState } from 'react';\nimport { useLocalFile } from '../../hooks/useLocalFile';\nimport { createAudioPlayer, disposeAudioPlayerRef } from '../../utils/audioPlayer';\nimport { useEscapeKey } from '../../hooks/useEscapeKey';\nimport { Tooltip } from '../common/Tooltip';\nimport { Button } from '../common/Button';\nimport { basename } from '../../utils/fileUtils';\nimport { mediaDrag } from '../../store/dragState';\nimport { Image as ImageIcon, Music, Pause, Play, RotateCcw, X } from '../icons/LucideLocal';\nimport { QUEUE_COLUMNS, resolveQueueGrid, useQueueColumnWidths } from './useQueueColumnWidths';\nimport './SDQueuePanel.css';\n\nconst STATUS_LABEL = {\n  pending: 'En attente',\n  submitting: 'Envoi...',\n  running: 'Génération...',\n  done: 'Terminé',\n  error: 'Erreur',\n};\n\nlet activeQueueAudioStopper = null;\n\nfunction formatCreatedAt(ts) {\n  if (!ts) return '-';\n  const date = new Date(ts);\n  if (Number.isNaN(date.getTime())) return '-';\n  const day = date.toLocaleDateString(getIntlLocale(), { day: '2-digit', month: '2-digit', year: '2-digit' });\n  const time = date.toLocaleTimeString(getIntlLocale(), { hour: '2-digit', minute: '2-digit' });\n  return `${day} ${time}`;\n}\n\nfunction progressPercent(progress) {\n  if (typeof progress !== 'number' || !Number.isFinite(progress)) return null;\n  return Math.max(0, Math.min(100, Math.round(progress * 100)));\n}\n\nfunction isActiveJob(job) {\n  return job.status === 'pending' || job.status === 'submitting' || job.status === 'running';\n}\n\nfunction startQueueMediaDrag(event, { kind, path, label, onDragStart = null }) {\n  if (!path || (kind !== 'audio' && kind !== 'image') || event.button !== 0) return;\n  if (event.target?.closest?.('input, textarea, [role=\"slider\"], .sd-queue-row-actions, .sd-result-play')) return;\n\n  const startX = event.clientX;\n  const startY = event.clientY;\n  let dragging = false;\n  let ghost = null;\n  let currentTarget = null;\n\n  function findTarget(x, y) {\n    return document.elementsFromPoint(x, y).find((el) => el.dataset.dropKind === kind) ?? null;\n  }\n\n  function onMove(ev) {\n    if (!dragging) {\n      if (Math.abs(ev.clientX - startX) < 6 && Math.abs(ev.clientY - startY) < 6) return;\n      dragging = true;\n      onDragStart?.();\n      mediaDrag.start(kind, path);\n      ghost = document.createElement('div');\n      ghost.className = 'sd-queue-drag-ghost';\n      ghost.textContent = label || basename(path);\n      document.body.appendChild(ghost);\n    }\n\n    ghost.style.left = `${ev.clientX + 14}px`;\n    ghost.style.top = `${ev.clientY - 14}px`;\n\n    const nextTarget = findTarget(ev.clientX, ev.clientY);\n    if (nextTarget !== currentTarget) {\n      currentTarget?.classList.remove('is-drop-over');\n      nextTarget?.classList.add('is-drop-over');\n      currentTarget = nextTarget;\n      ghost.classList.toggle('is-over-target', !!nextTarget);\n    }\n  }\n\n  function onUp() {\n    document.removeEventListener('pointermove', onMove);\n    document.removeEventListener('pointerup', onUp);\n    if (ghost) {\n      document.body.removeChild(ghost);\n      ghost = null;\n    }\n    currentTarget?.classList.remove('is-drop-over');\n\n    if (dragging && currentTarget) {\n      currentTarget.dispatchEvent(new CustomEvent('media-drop', {\n        bubbles: false,\n        detail: { path, kind },\n      }));\n    }\n    mediaDrag.end();\n  }\n\n  document.addEventListener('pointermove', onMove);\n  document.addEventListener('pointerup', onUp);\n}\n\nfunction ProgressRing({ progress }) {\n  const percent = progressPercent(progress);\n\n  if (percent == null) {\n    return <span className=\"sd-progress-ring sd-progress-ring-spin\" aria-hidden=\"true\" />;\n  }\n\n  return (\n    <Tooltip text={`Progression ${percent}%`}>\n      <span\n        className=\"sd-progress-ring\"\n        style={{ '--progress': `${percent}%` }}\n        aria-label={`Progression ${percent}%`}\n      />\n    </Tooltip>\n  );\n}\n\nfunction UsageBadge({ usage }) {\n  if (!usage) return <span className=\"sd-cell-muted\">-</span>;\n  return (\n    <Tooltip text={usage.detail} wrap>\n      <span className={`sd-usage-badge sd-usage-${usage.state}`}>\n        {usage.label}\n      </span>\n    </Tooltip>\n  );\n}\n\nfunction StatusBadge({ job }) {\n  const percent = progressPercent(job.progress);\n  const active = isActiveJob(job);\n  const label = active && percent != null ? `${percent}%` : (STATUS_LABEL[job.status] ?? job.status);\n\n  return (\n    <span className={`sd-job-badge sd-badge-${job.status}`}>\n      {active && <ProgressRing progress={job.progress} />}\n      {label}\n    </span>\n  );\n}\n\nfunction JobKind({ isImageJob }) {\n  const Icon = isImageJob ? ImageIcon : Music;\n  return (\n    <span className={`sd-kind-pill${isImageJob ? ' is-image' : ' is-audio'}`}>\n      <Icon className=\"sd-kind-icon\" strokeWidth={2} absoluteStrokeWidth />\n      {isImageJob ? 'Image' : 'Audio'}\n    </span>\n  );\n}\n\nfunction JobResultThumb({ path, onPreview }) {\n  const url = useLocalFile(path);\n  const draggedRef = useRef(false);\n\n  function handleClick(event) {\n    if (draggedRef.current) {\n      event.preventDefault();\n      draggedRef.current = false;\n      return;\n    }\n    onPreview(path);\n  }\n\n  return (\n    <Tooltip text=\"Glisser vers un placeholder image, cliquer pour prévisualiser\">\n      <button\n        className=\"sd-result-thumb\"\n        onPointerDown={(event) => startQueueMediaDrag(event, {\n          kind: 'image',\n          path,\n          label: basename(path),\n          onDragStart: () => { draggedRef.current = true; },\n        })}\n        onClick={handleClick}\n        aria-label={`Prévisualiser ${basename(path)}`}\n      >\n        {url ? (\n          <img src={url} alt=\"\" className=\"sd-result-img\" />\n        ) : (\n          <div className=\"sd-result-placeholder\" />\n        )}\n      </button>\n    </Tooltip>\n  );\n}\n\nfunction ImagePreviewModal({ path, onClose }) {\n  const url = useLocalFile(path);\n  const filename = basename(path);\n  useEscapeKey(true, () => onClose?.());\n  return (\n    <div className=\"modal-overlay sd-preview-overlay\" onMouseDown={onClose}>\n      <div className=\"modal-box sd-preview-box\" onMouseDown={e => e.stopPropagation()}>\n        <div className=\"modal-header\">\n          <span>{filename || 'Image générée'}</span>\n          <Button variant=\"icon\" className=\"modal-close\" onClick={onClose} aria-label=\"Fermer\">\n            <X className=\"sd-modal-close-icon\" strokeWidth={2} absoluteStrokeWidth />\n          </Button>\n        </div>\n        <div className=\"sd-preview-body\">\n          {url ? <img src={url} alt={filename} className=\"sd-preview-img\" /> : <div className=\"sd-result-placeholder\" />}\n        </div>\n      </div>\n    </div>\n  );\n}\n\nfunction QueueAudioButton({ path, filename }) {\n  const url = useLocalFile(path);\n  const audioRef = useRef(null);\n  const stopRef = useRef(null);\n  const [playing, setPlaying] = useState(false);\n\n  if (!stopRef.current) {\n    stopRef.current = () => {\n      const audio = audioRef.current;\n      if (audio) {\n        audio.pause();\n        audio.currentTime = 0;\n      }\n      setPlaying(false);\n      if (activeQueueAudioStopper === stopRef.current) activeQueueAudioStopper = null;\n    };\n  }\n\n  useEffect(() => {\n    setPlaying(false);\n    if (url) {\n      const audio = createAudioPlayer(url);\n      audioRef.current = audio;\n      audio.addEventListener('play', () => setPlaying(true));\n      audio.addEventListener('pause', () => setPlaying(false));\n      audio.addEventListener('ended', () => stopRef.current?.());\n    }\n    return () => {\n      if (activeQueueAudioStopper === stopRef.current) activeQueueAudioStopper = null;\n      disposeAudioPlayerRef(audioRef);\n    };\n  }, [url]);\n\n  async function togglePlayback(event) {\n    event.stopPropagation();\n    const audio = audioRef.current;\n    if (!audio || !url) return;\n\n    if (!audio.paused) {\n      stopRef.current?.();\n      return;\n    }\n\n    activeQueueAudioStopper?.();\n    activeQueueAudioStopper = stopRef.current;\n    try {\n      await audio.play();\n      setPlaying(true);\n    } catch {\n      if (activeQueueAudioStopper === stopRef.current) activeQueueAudioStopper = null;\n      setPlaying(false);\n    }\n  }\n\n  const Icon = playing ? Pause : Play;\n\n  return (\n    <>\n      <Button\n        variant=\"icon\"\n        size=\"sm\"\n        className={`sd-result-play${playing ? ' is-playing' : ''}`}\n        onClick={togglePlayback}\n        aria-label={`${playing ? 'Arrêter' : 'Lire'} ${filename}`}\n        title={playing ? 'Arrêter' : 'Lire'}\n        disabled={!url}\n      >\n        <Icon className=\"sd-row-icon\" strokeWidth={2} absoluteStrokeWidth />\n      </Button>\n    </>\n  );\n}\n\nfunction ResultCell({ job, isImageJob, onPreviewImage }) {\n  if (job.status === 'error') {\n    return (\n      <Tooltip text={job.errorMessage || 'Erreur de génération'} wrap className=\"sd-result-error-wrap\">\n        <span className=\"sd-result-error\">{job.errorMessage || 'Erreur de génération'}</span>\n      </Tooltip>\n    );\n  }\n\n  if (job.status !== 'done') {\n    return <span className=\"sd-cell-muted\">-</span>;\n  }\n\n  if (isImageJob) {\n    const paths = job.resultPaths ?? [];\n    if (paths.length === 0) return <span className=\"sd-cell-muted\">Aucun fichier</span>;\n    const visiblePaths = paths.slice(0, 2);\n    return (\n      <div className=\"sd-image-result-cell\">\n        <div className=\"sd-result-thumbs\">\n          {visiblePaths.map(path => (\n            <JobResultThumb key={path} path={path} onPreview={onPreviewImage} />\n          ))}\n          {paths.length > visiblePaths.length && (\n            <span className=\"sd-result-count\">+{paths.length - visiblePaths.length}</span>\n          )}\n        </div>\n        <Tooltip text={paths[0]} wrap className=\"sd-result-name-wrap\">\n          <span className=\"sd-result-name\">{basename(paths[0])}</span>\n        </Tooltip>\n      </div>\n    );\n  }\n\n  if (!job.resultPath) return <span className=\"sd-cell-muted\">Aucun fichier</span>;\n  const filename = basename(job.resultPath);\n  return (\n    <div\n      className=\"sd-audio-result-cell\"\n      onPointerDown={(event) => startQueueMediaDrag(event, {\n        kind: 'audio',\n        path: job.resultPath,\n        label: filename,\n      })}\n    >\n      <QueueAudioButton path={job.resultPath} filename={filename} />\n      <Tooltip text={job.resultPath} wrap className=\"sd-result-name-wrap\">\n        <span className=\"sd-result-name\">{filename}</span>\n      </Tooltip>\n    </div>\n  );\n}\n\nfunction QueueRow({ job, onRemove, onPreviewImage, onRegenerateImage, getAudioUsage, getImageUsage }) {\n  const isImageJob = job.kind !== 'audio';\n  const title = isImageJob ? (job.workflowName || 'Image IA') : (job.label || 'Audio IA');\n  const subtitle = isImageJob ? 'ComfyUI' : (job.voiceLabel || 'XTTS');\n  const usage = job.status === 'done'\n    ? (isImageJob ? getImageUsage?.(job) : getAudioUsage?.(job))\n    : null;\n  const target = job.targetLabel || '-';\n\n  return (\n    <div className={`sd-queue-row sd-job-${job.status}`}>\n      <div className=\"sd-queue-cell\">\n        <JobKind isImageJob={isImageJob} />\n      </div>\n      <div className=\"sd-queue-cell sd-title-cell\">\n        <span className=\"sd-cell-main\" title={title}>{title}</span>\n        <span className=\"sd-cell-sub\" title={subtitle}>{subtitle}</span>\n      </div>\n      <div className=\"sd-queue-cell\">\n        <span className=\"sd-cell-text\" title={target}>{target}</span>\n      </div>\n      <div className=\"sd-queue-cell sd-result-cell\">\n        <ResultCell\n          job={job}\n          isImageJob={isImageJob}\n          onPreviewImage={onPreviewImage}\n        />\n      </div>\n      <div className=\"sd-queue-cell\">\n        <StatusBadge job={job} />\n      </div>\n      <div className=\"sd-queue-cell\">\n        <UsageBadge usage={usage} />\n      </div>\n      <div className=\"sd-queue-cell\">\n        <span className=\"sd-cell-date\">{formatCreatedAt(job.createdAt)}</span>\n      </div>\n      <div className=\"sd-queue-row-actions\">\n        {job.status === 'done' && isImageJob && (\n          <Button\n            variant=\"icon\"\n            size=\"sm\"\n            className=\"sd-row-action\"\n            onClick={() => onRegenerateImage?.(job)}\n            aria-label=\"Régénérer l'image\"\n            title=\"Régénérer\"\n          >\n            <RotateCcw className=\"sd-row-icon\" strokeWidth={2} absoluteStrokeWidth />\n          </Button>\n        )}\n        {(job.status === 'done' || job.status === 'error') && (\n          <Button\n            variant=\"icon\"\n            size=\"sm\"\n            className=\"sd-row-action\"\n            onClick={() => onRemove(job.id)}\n            aria-label=\"Retirer de la file\"\n            title=\"Retirer\"\n          >\n            <X className=\"sd-row-icon\" strokeWidth={2} absoluteStrokeWidth />\n          </Button>\n        )}\n      </div>\n    </div>\n  );\n}\n\nexport function SDQueuePanel({\n  imageJobs = [],\n  audioJobs = [],\n  onRemoveImage,\n  onRemoveAudio,\n  getAudioUsage,\n  getImageUsage,\n  onRegenerateImage,\n  onClearDone,\n  onClose,\n  embedded = false,\n}) {\n  useMessageLanguage();\n  const jobs = [...imageJobs, ...audioJobs].map((job) => ({ ...job, errorMessage: presentUserMessage(job.errorMessage).message, progressLabel: presentTechnicalMessage(job.progressLabel) })).sort((a, b) => (b.createdAt ?? 0) - (a.createdAt ?? 0));\n  const hasDone = jobs.some(j => j.status === 'done' || j.status === 'error');\n  const [previewPath, setPreviewPath] = useState(null);\n  const [tableWidth, setTableWidth] = useState(0);\n  const tableRef = useRef(null);\n  const headerRef = useRef(null);\n  const scrollRef = useRef(null);\n  const { colWidths, colWidthsRef, setColWidths, persistColWidths } = useQueueColumnWidths();\n  const resolvedGrid = useMemo(() => resolveQueueGrid(colWidths, tableWidth), [colWidths, tableWidth]);\n  useEscapeKey(!embedded && !previewPath, () => onClose?.());\n\n  useEffect(() => {\n    const table = tableRef.current;\n    if (!table) return undefined;\n\n    function syncWidth() {\n      setTableWidth(table.clientWidth);\n    }\n\n    if (typeof ResizeObserver === 'undefined') {\n      syncWidth();\n      window.addEventListener('resize', syncWidth);\n      return () => window.removeEventListener('resize', syncWidth);\n    }\n\n    const observer = new ResizeObserver(syncWidth);\n    observer.observe(table);\n    syncWidth();\n    return () => observer.disconnect();\n  }, [jobs.length]);\n\n  useEffect(() => {\n    const scroll = scrollRef.current;\n    const header = headerRef.current;\n    if (!scroll || !header) return undefined;\n\n    function syncGutter() {\n      const gutter = scroll.offsetWidth - scroll.clientWidth;\n      header.style.paddingRight = `${9 + gutter}px`;\n    }\n\n    if (typeof ResizeObserver === 'undefined') {\n      syncGutter();\n      window.addEventListener('resize', syncGutter);\n      return () => window.removeEventListener('resize', syncGutter);\n    }\n\n    const observer = new ResizeObserver(syncGutter);\n    observer.observe(scroll);\n    syncGutter();\n    return () => observer.disconnect();\n  }, [jobs.length, resolvedGrid.grid]);\n\n  function startResize(event, col) {\n    event.preventDefault();\n    const startX = event.clientX;\n    const startWidth = resolvedGrid.widths?.[col.id] ?? colWidthsRef.current[col.id] ?? col.defaultWidth;\n    document.body.style.cursor = 'col-resize';\n\n    function onMove(moveEvent) {\n      const delta = moveEvent.clientX - startX;\n      const width = Math.max(col.minWidth, startWidth + delta);\n      setColWidths({ ...colWidthsRef.current, [col.id]: width });\n    }\n\n    function onUp() {\n      document.body.style.cursor = '';\n      document.removeEventListener('pointermove', onMove);\n      document.removeEventListener('pointerup', onUp);\n      persistColWidths();\n    }\n\n    document.addEventListener('pointermove', onMove);\n    document.addEventListener('pointerup', onUp);\n  }\n\n  const tableStyle = {\n    '--sd-queue-grid': resolvedGrid.grid,\n    '--sd-queue-min-width': resolvedGrid.minWidth,\n  };\n\n  const content = (\n    <>\n      <div className={embedded ? 'sd-queue-embedded-header' : 'modal-header'}>\n        <span>Générations IA</span>\n        <div className=\"sd-queue-header-actions\">\n          {hasDone && (\n            <Button size=\"sm\" onClick={onClearDone}>\n              Effacer terminées\n            </Button>\n          )}\n          {!embedded && (\n            <Button variant=\"icon\" className=\"modal-close\" onClick={onClose} aria-label=\"Fermer\">\n              <X className=\"sd-modal-close-icon\" strokeWidth={2} absoluteStrokeWidth />\n            </Button>\n          )}\n        </div>\n      </div>\n\n      <div className=\"sd-queue-body\">\n        {jobs.length === 0 ? (\n          <div className=\"sd-queue-empty\">Aucune génération en cours.</div>\n        ) : (\n          <div className=\"sd-queue-table\" ref={tableRef} style={tableStyle}>\n            <div className=\"sd-queue-table-header\" ref={headerRef}>\n              {QUEUE_COLUMNS.map((col) => (\n                <div key={col.id} className=\"sd-col-head\">\n                  <span className=\"sd-col-label\">{col.label}</span>\n                  {col.id !== 'actions' && (\n                    <span\n                      className=\"sd-col-resize\"\n                      onPointerDown={(event) => startResize(event, col)}\n                    />\n                  )}\n                </div>\n              ))}\n            </div>\n            <div className=\"sd-queue-table-scroll\" ref={scrollRef}>\n              {jobs.map(job => (\n                <QueueRow\n                  key={job.id}\n                  job={job}\n                  onRemove={job.kind === 'audio' ? onRemoveAudio : onRemoveImage}\n                  onPreviewImage={setPreviewPath}\n                  onRegenerateImage={onRegenerateImage}\n                  getAudioUsage={getAudioUsage}\n                  getImageUsage={getImageUsage}\n                />\n              ))}\n            </div>\n          </div>\n        )}\n      </div>\n      {previewPath && (\n        <ImagePreviewModal path={previewPath} onClose={() => setPreviewPath(null)} />\n      )}\n    </>\n  );\n\n  if (embedded) {\n    return <div className=\"sd-queue-embedded\">{content}</div>;\n  }\n\n  return (\n    <div className=\"modal-overlay\">\n      <div className=\"modal-box sd-queue-box\">\n        {content}\n      </div>\n    </div>\n  );\n}\n",
  "src/components/SDQueuePanel/useQueueColumnWidths.js": "import { useRef, useState } from 'react';\nimport { KEYS, read, write } from '../../store/persistentSettings';\n\nexport const QUEUE_COLUMNS = [\n  { id: 'type', label: 'Type', defaultWidth: 76, minWidth: 62, grow: 0.2 },\n  { id: 'name', label: 'Nom', defaultWidth: 220, minWidth: 130, grow: 1.3 },\n  { id: 'target', label: 'Destination', defaultWidth: 190, minWidth: 92, grow: 1 },\n  { id: 'result', label: 'Résultat', defaultWidth: 300, minWidth: 130, grow: 1.6 },\n  { id: 'status', label: 'Statut', defaultWidth: 96, minWidth: 82, grow: 0.25 },\n  { id: 'usage', label: 'Usage', defaultWidth: 100, minWidth: 76, grow: 0.25 },\n  { id: 'date', label: 'Date', defaultWidth: 92, minWidth: 72, grow: 0.2 },\n  { id: 'actions', label: '', defaultWidth: 58, minWidth: 48, grow: 0 },\n];\n\nconst RESIZABLE_COLUMNS = QUEUE_COLUMNS.filter((col) => col.id !== 'actions');\nconst DEFAULT_COL_WIDTHS = Object.fromEntries(QUEUE_COLUMNS.map((col) => [col.id, col.defaultWidth]));\nconst GRID_GAP = 8;\nconst GRID_OUTER_PADDING = 44;\n\nfunction clampWidth(col, width) {\n  const numeric = Number(width);\n  return Math.max(col.minWidth, Number.isFinite(numeric) ? numeric : col.defaultWidth);\n}\n\nfunction loadQueueColWidths() {\n  const saved = read(KEYS.AI_QUEUE_COL_WIDTHS, { parse: JSON.parse });\n  if (!saved || Array.isArray(saved)) return { ...DEFAULT_COL_WIDTHS };\n  const next = { ...DEFAULT_COL_WIDTHS };\n  for (const col of QUEUE_COLUMNS) {\n    if (saved[col.id] != null) next[col.id] = clampWidth(col, saved[col.id]);\n  }\n  return next;\n}\n\nfunction fitWidthsToContainer(widths, containerWidth) {\n  const next = Object.fromEntries(QUEUE_COLUMNS.map((col) => [col.id, clampWidth(col, widths[col.id])]));\n  const contentWidth = Math.max(0, (containerWidth || 0) - GRID_OUTER_PADDING);\n  if (!contentWidth) return next;\n\n  const gapTotal = GRID_GAP * (QUEUE_COLUMNS.length - 1);\n  const widthTotal = () => QUEUE_COLUMNS.reduce((sum, col) => sum + next[col.id], gapTotal);\n  let delta = contentWidth - widthTotal();\n\n  if (delta > 0) {\n    const growTotal = RESIZABLE_COLUMNS.reduce((sum, col) => sum + col.grow, 0);\n    if (growTotal > 0) {\n      for (const col of RESIZABLE_COLUMNS) {\n        next[col.id] += delta * (col.grow / growTotal);\n      }\n    }\n    return next;\n  }\n\n  let remaining = -delta;\n  let shrinkable = RESIZABLE_COLUMNS.filter((col) => next[col.id] > col.minWidth);\n  while (remaining > 0.5 && shrinkable.length > 0) {\n    const available = shrinkable.reduce((sum, col) => sum + (next[col.id] - col.minWidth), 0);\n    if (available <= 0) break;\n    const consumed = Math.min(remaining, available);\n    for (const col of shrinkable) {\n      const share = consumed * ((next[col.id] - col.minWidth) / available);\n      next[col.id] = Math.max(col.minWidth, next[col.id] - share);\n    }\n    remaining -= consumed;\n    shrinkable = shrinkable.filter((col) => next[col.id] > col.minWidth + 0.5);\n  }\n  return next;\n}\n\nexport function resolveQueueGrid(widths, containerWidth) {\n  const fitted = fitWidthsToContainer(widths, containerWidth);\n  const gridWidth = QUEUE_COLUMNS.reduce(\n    (sum, col) => sum + Math.round(fitted[col.id]),\n    GRID_GAP * (QUEUE_COLUMNS.length - 1),\n  );\n\n  return {\n    grid: QUEUE_COLUMNS.map((col) => `${Math.round(fitted[col.id])}px`).join(' '),\n    minWidth: `${gridWidth + GRID_OUTER_PADDING}px`,\n    widths: fitted,\n  };\n}\n\nexport function useQueueColumnWidths() {\n  const [colWidths, setColWidthsState] = useState(loadQueueColWidths);\n  const colWidthsRef = useRef(colWidths);\n\n  function setColWidths(newWidths) {\n    colWidthsRef.current = newWidths;\n    setColWidthsState(newWidths);\n  }\n\n  function persistColWidths() {\n    write(KEYS.AI_QUEUE_COL_WIDTHS, colWidthsRef.current, { serialize: JSON.stringify });\n  }\n\n  return { colWidths, colWidthsRef, setColWidths, persistColWidths };\n}\n",
  "src/components/TextImageGenerator/TextImagePromptModal.jsx": "import { useState, useRef, useEffect } from 'react';\nimport { createPortal } from 'react-dom';\nimport { generateTextImage } from './generateTextImage';\nimport { drawTextImage, TEXT_IMG_W, TEXT_IMG_H } from './drawTextImage';\nimport { Button } from '../common/Button';\nimport { useEscapeKey } from '../../hooks/useEscapeKey';\nimport { useProjectContext } from '../../store/ProjectContext';\nimport './TextImagePromptModal.css';\n\nconst OVERLAY_STYLE = {\n  position: 'fixed',\n  inset: 0,\n  background: 'rgba(0, 0, 0, 0.55)',\n  display: 'flex',\n  alignItems: 'center',\n  justifyContent: 'center',\n  zIndex: 10000,\n  backdropFilter: 'blur(2px)',\n};\n\nexport function TextImagePromptModal({ defaultText, workspaceDir: workspaceOverride, onConfirm, onCancel }) {\n  const [text, setText] = useState(defaultText || '');\n  const [generating, setGenerating] = useState(false);\n  const canvasRef = useRef(null);\n  const inputRef = useRef(null);\n  const { workspaceDir: contextWorkspaceDir, mediaStorage } = useProjectContext();\n\n  useEffect(() => {\n    inputRef.current?.focus();\n    inputRef.current?.select();\n  }, []);\n\n  useEffect(() => {\n    const canvas = canvasRef.current;\n    if (!canvas) return;\n    drawTextImage(canvas.getContext('2d'), text || 'Sans titre');\n  }, [text]);\n\n  async function handleGenerate() {\n    if (generating) return;\n    setGenerating(true);\n    try {\n      const path = await generateTextImage(\n        text || 'Sans titre',\n        workspaceOverride || contextWorkspaceDir,\n        { mediaStorage },\n      );\n      onConfirm(path);\n    } finally {\n      setGenerating(false);\n    }\n  }\n\n  // Via la pile Escape partagée : ferme cette modale sans atteindre la surface\n  // du dessous (funnel/éditeur), quel que soit l'élément qui a le focus.\n  useEscapeKey(true, onCancel);\n\n  function handleKeyDown(e) {\n    if (e.key === 'Enter') handleGenerate();\n  }\n\n  return createPortal(\n    // data-modal-surface : overlay à styles inline, reconnu par la garde des\n    // raccourcis globaux (utils/modalSurfaces.js).\n    <div style={OVERLAY_STYLE} data-modal-surface=\"\" onClick={onCancel}>\n      <div className=\"text-img-box\" onClick={e => e.stopPropagation()}>\n        <div className=\"text-img-header\">Générer une image-titre</div>\n        <div className=\"text-img-body\">\n          <input\n            ref={inputRef}\n            className=\"field-input text-img-input\"\n            value={text}\n            onChange={e => setText(e.target.value)}\n            onKeyDown={handleKeyDown}\n            placeholder=\"Texte à afficher\"\n            maxLength={200}\n          />\n          <canvas\n            ref={canvasRef}\n            width={TEXT_IMG_W}\n            height={TEXT_IMG_H}\n            className=\"text-img-preview\"\n          />\n        </div>\n        <div className=\"text-img-footer\">\n          <Button variant=\"ghost\" onClick={onCancel}>Annuler</Button>\n          <Button variant=\"primary-violet\" onClick={handleGenerate} disabled={generating}>\n            {generating ? 'Génération…' : 'Générer'}\n          </Button>\n        </div>\n      </div>\n    </div>,\n    document.body,\n  );\n}\n",
  "src/components/TextImageGenerator/drawTextImage.js": "export const TEXT_IMG_W = 320;\nexport const TEXT_IMG_H = 240;\n\nexport function drawTextImage(ctx, text) {\n  const label = (text || 'Sans titre').trim() || 'Sans titre';\n  ctx.fillStyle = '#000000';\n  ctx.fillRect(0, 0, TEXT_IMG_W, TEXT_IMG_H);\n  ctx.fillStyle = '#ffffff';\n  ctx.textAlign = 'center';\n  ctx.textBaseline = 'middle';\n  drawAutoText(ctx, label, TEXT_IMG_W / 2, TEXT_IMG_H / 2, 280, TEXT_IMG_H - 32);\n}\n\nfunction drawAutoText(ctx, text, cx, cy, maxW, maxH) {\n  const words = text.split(' ');\n  for (let size = 36; size >= 12; size -= 2) {\n    ctx.font = `600 ${size}px sans-serif`;\n    const lines = buildLines(ctx, words, maxW);\n    const lineH = size * 1.3;\n    const totalH = lines.length * lineH;\n    if (totalH <= maxH) {\n      const startY = cy - totalH / 2 + lineH / 2;\n      lines.forEach((line, i) => ctx.fillText(line, cx, startY + i * lineH));\n      return;\n    }\n  }\n  ctx.font = '600 12px sans-serif';\n  const lines = buildLines(ctx, words, maxW);\n  const lineH = 12 * 1.3;\n  const startY = cy - (lines.length * lineH) / 2 + lineH / 2;\n  lines.forEach((line, i) => ctx.fillText(line, cx, startY + i * lineH));\n}\n\nfunction buildLines(ctx, words, maxW) {\n  const lines = [];\n  let current = '';\n  for (const word of words) {\n    const test = current ? `${current} ${word}` : word;\n    if (ctx.measureText(test).width > maxW && current) {\n      lines.push(current);\n      current = word;\n    } else {\n      current = test;\n    }\n  }\n  if (current) lines.push(current);\n  return lines;\n}\n",
  "src/components/TextImageGenerator/generateTextImage.js": "import { beginProjectMediaOutput } from '../../store/projectMediaOutput';\nimport { logger } from '../../utils/logger';\nimport { writeFile, mkdir } from '@tauri-apps/plugin-fs';\nimport { appCacheDir, join } from '@tauri-apps/api/path';\nimport { TEXT_IMG_W, TEXT_IMG_H, drawTextImage } from './drawTextImage';\nimport { TEMP_IMAGES_DIR } from '../../utils/tempDirs';\n\n// Un nom de fichier imposé (`exemple-<uuid>.png` pour les exemples du graphe)\n// doit rester un simple nom PNG : jamais un chemin. Sans lui, le nom historique\n// horodaté est conservé pour les autres appelants.\nconst SAFE_IMAGE_FILENAME = /^[A-Za-z0-9][A-Za-z0-9._-]{0,120}\\.png$/;\n\nexport async function generateTextImage(text, workspaceDir = '', { filename: requestedFilename = null, mediaStorage = null } = {}) {\n  if (requestedFilename !== null && !SAFE_IMAGE_FILENAME.test(requestedFilename)) {\n    throw new TypeError('Nom de fichier image invalide.');\n  }\n  const output = workspaceDir?.trim() ? beginProjectMediaOutput(mediaStorage ?? { root: workspaceDir, ephemeral: true }) : null;\n  try {\n    const canvas = document.createElement('canvas');\n    canvas.width = TEXT_IMG_W;\n    canvas.height = TEXT_IMG_H;\n    drawTextImage(canvas.getContext('2d'), text);\n\n    const blob = await new Promise(r => canvas.toBlob(r, 'image/png'));\n    const buf = await blob.arrayBuffer();\n    const filename = requestedFilename ?? `edited_${Date.now()}.png`;\n\n    const managedWorkspace = workspaceDir?.trim();\n    if (managedWorkspace) {\n      try {\n        return await (async () => {\n          const destDir = await output.directory('images-generees');\n          await mkdir(destDir, { recursive: true });\n          for (let index = 1; index <= 1000; index += 1) {\n            const destPath = await join(destDir, index === 1 ? filename : filename.replace(/\\.png$/, `_${index}.png`));\n            try { await writeFile(destPath, new Uint8Array(buf), { createNew: true }); return destPath; }\n            catch (error) { if (!/already exists|file exists|os error (80|183)/i.test(String(error))) throw error; }\n          }\n          throw new Error('Trop d’images portent ce nom.');\n        })();\n      } catch (error) {\n        logger.warn('text-image:workspace-output-failed-cache-fallback', error);\n        mediaStorage?.onFallback?.();\n      }\n    }\n\n    const cacheDir = await join(await appCacheDir(), TEMP_IMAGES_DIR);\n    await mkdir(cacheDir, { recursive: true });\n    const cachePath = await join(cacheDir, filename);\n    await writeFile(cachePath, new Uint8Array(buf));\n    return cachePath;\n  } finally { output?.release(); }\n}\n",
  "src/hooks/useAiGeneration.js": "import { useState } from 'react';\nimport { sanitizeImportedName } from '../store/projectStore';\nimport { getImageJobTargetLabel } from '../store/aiJobLabels';\nimport { captureProjectMediaJob } from '../store/projectMediaOutput';\nimport { applyGeneratedAudioToTarget as dispatchGeneratedAudioToTarget } from '../store/generatedAudioTarget';\n\nfunction getTtsStoryName(text) {\n  const normalized = String(text || '').replace(/\\s+/g, ' ').trim();\n  if (!normalized) return '';\n  const punctuationIndexes = ['.', '!', '?']\n    .map((mark) => normalized.indexOf(mark))\n    .filter((index) => index >= 0);\n  const firstStop = punctuationIndexes.length > 0 ? Math.min(...punctuationIndexes) : -1;\n  const firstSentence = firstStop >= 0 ? normalized.slice(0, firstStop) : normalized;\n  const clipped = firstSentence.length > 72 ? `${firstSentence.slice(0, 72).trim()}...` : firstSentence;\n  return sanitizeImportedName(clipped, '');\n}\n\n// Dispatch de génération IA extrait d'AppContent : ouverture de la file IA,\n// génération/régénération d'image (SD/ComfyUI),\n// génération de voix (XTTS) et application d'un audio généré à sa cible.\n//\n// Ordre d'appel critique dans l'hôte : `applyGeneratedAudioToTarget` est passé à\n// `useXttsJobs` — ce hook doit donc être appelé AVANT `useSDJobs`/`useXttsJobs`,\n// pour que la valeur retournée existe au moment du câblage (fonction jadis\n// hoistée, désormais valeur de retour).\nexport function useAiGeneration({\n  store,\n  mediaStorageRef,\n  sdStore,\n  xttsStore,\n  projectIndex,\n  xttsSettings,\n  setBottomPanelOpen,\n  setBottomPanelTab,\n}) {\n  const [sdGenerateOpen, setSdGenerateOpen] = useState(false);\n  const [sdGenerateContext, setSdGenerateContext] = useState(null);\n\n  function handleOpenAiQueue() {\n    setBottomPanelTab('ai');\n    setBottomPanelOpen(true);\n  }\n\n  function handleOpenSDGenerate(context = null) {\n    setSdGenerateContext(context);\n    setSdGenerateOpen(true);\n  }\n\n  function handleRegenerateImageJob(job) {\n    if (!job) return;\n    setSdGenerateContext({ regenerateJob: job });\n    setSdGenerateOpen(true);\n  }\n\n  async function handleSDGenerate(workflowId, workflowName, params) {\n    const projectEpoch = store.workEpochRef.current;\n    const mediaOutput = await captureProjectMediaJob(mediaStorageRef.current);\n    sdStore.addJob(workflowId, workflowName, params, {\n      mediaOutput,\n      projectEpoch,\n      fieldId: sdGenerateContext?.fieldId || null,\n      targetLabel: getImageJobTargetLabel(sdGenerateContext, projectIndex),\n    });\n    handleOpenAiQueue();\n  }\n\n  function applyGeneratedAudioToTarget(target, path, job = null) {\n    return dispatchGeneratedAudioToTarget({ target, path, job, store, projectIndex, getStoryName: getTtsStoryName });\n  }\n\n  async function handleQueueXttsGenerate(job) {\n    const projectEpoch = store.workEpochRef.current;\n    const settings = { ...xttsSettings };\n    const target = job.target ? { projectEpoch, ...job.target } : null;\n    const mediaOutput = await captureProjectMediaJob(mediaStorageRef.current);\n    xttsStore.addJob({\n      label: job.targetLabel || 'Audio IA',\n      targetLabel: job.targetLabel || 'Audio IA',\n      voiceLabel: job.voiceLabel || 'XTTS',\n      // Toute cible est liée au travail qui l'a demandée : une voix revenue\n      // après l'ouverture d'un autre projet ne s'y applique pas (garde de\n      // `applyGeneratedAudioToTarget`). Une cible qui porte déjà son époque la\n      // garde.\n      target,\n      request: job.request,\n      settings,\n      mediaOutput,\n      projectEpoch,\n    });\n    handleOpenAiQueue();\n  }\n\n  function relocateMediaJobPaths(remap) {\n    for (const job of xttsStore.jobs) {\n      if (job.resultPath) xttsStore.updateJob(job.id, { resultPath: remap(job.resultPath) });\n    }\n    for (const job of sdStore.jobs) {\n      if (job.resultPaths?.length) sdStore.updateJob(job.id, { resultPaths: job.resultPaths.map(remap) });\n    }\n  }\n\n  return {\n    relocateMediaJobPaths,\n    handleOpenAiQueue,\n    handleOpenSDGenerate,\n    handleRegenerateImageJob,\n    handleSDGenerate,\n    applyGeneratedAudioToTarget,\n    handleQueueXttsGenerate,\n    sdGenerate: {\n      open: sdGenerateOpen,\n      context: sdGenerateContext,\n      close: () => {\n        setSdGenerateOpen(false);\n        setSdGenerateContext(null);\n      },\n    },\n  };\n}\n",
  "src/hooks/useAiJobUsage.js": "import { useCallback } from 'react';\nimport { pathKey } from '../utils/fileUtils';\nimport { advancedMediaUsageForPaths } from '../store/advancedAuthoring/mediaUsage';\nimport { isAdvancedProject } from '../store/projectWorkState';\n\nconst samePath = (a, b) => pathKey(a) === pathKey(b);\n\n// La réponse d'un projet graphe, pour l'audio comme pour l'image. Trois issues,\n// et la troisième est la raison d'être de cette branche : sans elle, un projet\n// graphe recevait « Non utilisé » — une affirmation — là où l'arbre parcouru\n// était simplement vide. Un auteur supprime un fichier sur cette phrase.\nfunction advancedJobUsage(project, advancedUsages, paths, words) {\n  const found = advancedMediaUsageForPaths(project, advancedUsages, paths, samePath);\n  if (!found) return { state: 'unused', label: words.unused, detail: words.noBinding };\n  if (!found.bound) return { state: 'unused', label: words.unused, detail: words.noBinding };\n  if (!found.known) {\n    return {\n      state: 'unknown',\n      label: 'Usage non calculé',\n      detail: 'Le fichier est lié au document. Les écrans qui l’emploient ne sont pas encore connus : ouvre l’éditeur du projet pour les établir.',\n    };\n  }\n  if (found.usages.length === 0) {\n    return { state: 'unused', label: words.unused, detail: words.boundUnreferenced };\n  }\n  const detail = found.usages\n    .map((usage) => `Écran : ${usage.label} · Champ : ${usage.field === 'image' ? 'image' : 'audio'}`)\n    .join(' ; ');\n  return {\n    state: 'used',\n    label: found.usages.length === 1 ? words.used : `${words.used} ×${found.usages.length}`,\n    detail,\n  };\n}\n\nconst AUDIO_FIELD_LABELS = {\n  rootAudio: 'audio d’accueil',\n  nightModeAudio: 'audio de fin',\n  itemAudio: 'audio de sélection',\n  audio: 'audio de lecture',\n  afterPlaybackPromptAudio: 'audio après lecture',\n  afterPlaybackSequence: 'audio de fin intermédiaire',\n  afterPlaybackHomeStep: 'audio Home pendant lecture',\n  coverAudio: 'audio de couverture',\n};\n\nfunction audioFieldLabel(field) {\n  return AUDIO_FIELD_LABELS[field] || 'champ audio';\n}\n\nexport function useAiJobUsage({ project, projectIndex, advancedMediaUsages = null }) {\n  const getAudioJobUsage = useCallback((job) => {\n    if (!job || job.kind !== 'audio' || job.status !== 'done' || !job.resultPath) return null;\n    if (isAdvancedProject(project)) {\n      return advancedJobUsage(project, advancedMediaUsages, [job.resultPath], {\n        used: 'Utilisé',\n        unused: 'Non utilisé',\n        noBinding: 'Aucune liaison du document ne pointe vers ce fichier.',\n        boundUnreferenced: 'Le fichier est lié au document, mais aucun écran ne l’emploie.',\n      });\n    }\n    const resultPath = pathKey(job.resultPath);\n    const usages = [];\n\n    function addUsage(path, nodeName, field) {\n      if (path && pathKey(path) === resultPath) {\n        usages.push(`Nœud : ${nodeName} · Champ : ${audioFieldLabel(field)}`);\n      }\n    }\n\n    addUsage(project?.rootAudio, project?.name || 'Accueil', 'rootAudio');\n    addUsage(project?.nightModeAudio, 'Fin', 'nightModeAudio');\n\n    for (const flatEntry of projectIndex.flatEntries ?? []) {\n      const entry = flatEntry.entry ?? flatEntry;\n      const nodeName = entry.name || (entry.type === 'menu' ? 'Menu sans titre' : entry.type === 'zip' ? 'ZIP sans titre' : 'Histoire sans titre');\n      if (entry.type === 'menu') {\n        addUsage(entry.audio, nodeName, 'audio');\n      } else if (entry.type === 'story') {\n        addUsage(entry.itemAudio, nodeName, 'itemAudio');\n        addUsage(entry.audio, nodeName, 'audio');\n        addUsage(entry.afterPlaybackPromptAudio, nodeName, 'afterPlaybackPromptAudio');\n        for (const step of entry.afterPlaybackSequence ?? []) {\n          addUsage(step.audio, nodeName, 'afterPlaybackSequence');\n        }\n        addUsage(entry.afterPlaybackHomeStep?.audio, nodeName, 'afterPlaybackHomeStep');\n      } else if (entry.type === 'zip') {\n        addUsage(entry.coverAudio, nodeName, 'coverAudio');\n      }\n    }\n\n    if (usages.length > 0) {\n      return {\n        state: 'used',\n        label: usages.length === 1 ? 'Utilisé' : `Utilisé ×${usages.length}`,\n        detail: usages.join(' ; '),\n      };\n    }\n\n    const target = job.target;\n    let currentPath = null;\n    let targetExists = true;\n    let nodeName = null;\n    let fieldLabel = audioFieldLabel(target?.field);\n\n    switch (target?.kind) {\n      case 'root':\n        currentPath = project?.[target.field] ?? null;\n        nodeName = project?.name || 'Accueil';\n        break;\n      case 'rootStory':\n        currentPath = project?.rootEntries?.[0]?.[target.field] ?? null;\n        nodeName = project?.rootEntries?.[0]?.name || 'Histoire principale';\n        break;\n      case 'menu': {\n        const entry = projectIndex.entryById.get(target.entryId);\n        targetExists = !!entry;\n        currentPath = entry?.[target.field] ?? null;\n        nodeName = entry?.name || 'Menu sans titre';\n        break;\n      }\n      case 'story': {\n        const entry = projectIndex.entryById.get(target.entryId);\n        targetExists = !!entry;\n        currentPath = entry?.[target.field] ?? null;\n        nodeName = entry?.name || 'Histoire sans titre';\n        break;\n      }\n      case 'storySequence': {\n        const entry = projectIndex.entryById.get(target.entryId);\n        const step = entry?.afterPlaybackSequence?.find((item) => item.id === target.stepId);\n        targetExists = !!entry && !!step;\n        currentPath = step?.[target.field] ?? null;\n        nodeName = `${entry?.name || 'Histoire sans titre'} · ${step?.name || 'Sequence de fin'}`;\n        fieldLabel = audioFieldLabel('afterPlaybackSequence');\n        break;\n      }\n      case 'storyHomeStep': {\n        const entry = projectIndex.entryById.get(target.entryId);\n        targetExists = !!entry && !!entry.afterPlaybackHomeStep;\n        currentPath = entry?.afterPlaybackHomeStep?.[target.field] ?? null;\n        nodeName = `${entry?.name || 'Histoire sans titre'} · Home pendant lecture`;\n        fieldLabel = audioFieldLabel('afterPlaybackHomeStep');\n        break;\n      }\n      default:\n        targetExists = false;\n        break;\n    }\n\n    if (!targetExists) {\n      return { state: 'unused', label: 'Non utilisé', detail: `${fieldLabel} n’existe plus` };\n    }\n    if (pathKey(currentPath) === resultPath) {\n      return { state: 'used', label: 'Utilisé', detail: `Nœud : ${nodeName} · Champ : ${fieldLabel}` };\n    }\n    return { state: 'unused', label: 'Non utilisé', detail: `Nœud : ${nodeName} · Champ modifié : ${fieldLabel}` };\n  }, [project, projectIndex, advancedMediaUsages]);\n\n  const getImageJobUsage = useCallback((job) => {\n    if (!job || job.kind === 'audio' || job.status !== 'done' || !job.resultPaths?.length) return null;\n    if (isAdvancedProject(project)) {\n      return advancedJobUsage(project, advancedMediaUsages, job.resultPaths, {\n        used: 'Utilisée',\n        unused: 'Non utilisée',\n        noBinding: 'Aucune liaison du document ne pointe vers ces fichiers.',\n        boundUnreferenced: 'Le fichier est lié au document, mais aucun écran ne l’emploie.',\n      });\n    }\n    const resultSet = new Set(job.resultPaths.map(pathKey));\n    const usages = [];\n\n    function addUsage(path, nodeName, fieldLabel) {\n      if (path && resultSet.has(pathKey(path))) {\n        usages.push(`${nodeName} · ${fieldLabel}`);\n      }\n    }\n\n    const rootLabel = project?.projectName || project?.packMetadata?.title || 'Accueil';\n    addUsage(project?.rootImage, rootLabel, 'image d’accueil');\n    addUsage(project?.thumbnailImage, rootLabel, 'vignette');\n\n    for (const flatEntry of projectIndex.flatEntries ?? []) {\n      const entry = flatEntry.entry ?? flatEntry;\n      const nodeName = entry.name || (entry.type === 'menu' ? 'Menu sans titre' : 'Histoire sans titre');\n      addUsage(entry.image, nodeName, entry.type === 'menu' ? 'image du menu' : 'image de l’histoire');\n      addUsage(entry.itemImage, nodeName, 'image de sélection');\n      addUsage(entry.coverImage, nodeName, 'couverture');\n    }\n\n    if (usages.length > 0) {\n      return {\n        state: 'used',\n        label: usages.length === 1 ? 'Utilisée' : `Utilisées ×${usages.length}`,\n        detail: usages.join(' ; '),\n      };\n    }\n    return { state: 'unused', label: 'Non utilisée', detail: 'Aucune image de cette génération n’est assignée au projet.' };\n  }, [project, projectIndex, advancedMediaUsages]);\n\n  return { getAudioJobUsage, getImageJobUsage };\n}\n",
  "src/hooks/useSDJobs.js": "import { presentUserMessage, userMessageTransport } from '../i18n/userMessage.js';\nimport { useEffect, useRef } from 'react';\nimport { invoke } from '@tauri-apps/api/core';\nimport { listen } from '@tauri-apps/api/event';\nimport { logger } from '../utils/logger';\nimport { isTauriRuntime } from '../utils/tauriRuntime';\nimport { releaseTauriListener } from '../utils/tauriListener';\n\nconst MAX_CONCURRENT_SD_JOBS = 1;\n\nexport function useSDJobs(sdStore, workspaceDir = null, onMediaCreated = null) {\n  const polling = useRef(new Set());\n  const finished = useRef(new Set());\n  useEffect(() => {\n    if (!isTauriRuntime()) return undefined;\n\n    let cancelled = false;\n    let unlisten = null;\n    listen('comfyui-progress', (event) => {\n      if (cancelled) return;\n      const payload = event.payload || {};\n      if (!payload.jobId) return;\n      if (payload.error) {\n        logger.warn('comfyui:progress-error', payload.error);\n        return;\n      }\n      if (typeof payload.progress === 'number') {\n        sdStore.updateJob(payload.jobId, {\n          progress: payload.progress,\n          progressLabel: payload.progressLabel || null,\n        });\n      }\n    }).then((fn) => {\n      if (cancelled) releaseTauriListener(fn);\n      else unlisten = fn;\n    }).catch((error) => logger.error('comfyui:listen-error', error));\n\n    return () => {\n      cancelled = true;\n      releaseTauriListener(unlisten);\n    };\n  }, []);\n\n  useEffect(() => {\n    if (!isTauriRuntime()) return;\n\n    const active = sdStore.jobs.filter(j => j.status === 'submitting' || j.status === 'running');\n    if (active.length >= MAX_CONCURRENT_SD_JOBS) return;\n    const next = sdStore.jobs.find(j => j.status === 'pending');\n    if (!next) return;\n    sdStore.updateJob(next.id, { status: 'submitting', progress: null, progressLabel: null });\n    invoke('comfyui_watch_progress', {\n      settings: sdStore.sdSettings,\n      clientId: next.clientId,\n      jobId: next.id,\n    }).catch(e => logger.warn('comfyui:watch-progress-error', presentUserMessage(e).message));\n    invoke('comfyui_submit_job', {\n      settings: sdStore.sdSettings,\n      request: {\n        workflowId: next.workflowId,\n        positivePrompt: next.params.positivePrompt,\n        negativePrompt: next.params.negativePrompt,\n        seed: next.params.seed,\n        steps: next.params.steps,\n        cfg: next.params.cfg,\n        loraStrength: next.params.loraStrength,\n        referenceImagePath: next.params.referenceImagePath || null,\n        clientId: next.clientId,\n      },\n    })\n      .then(promptId => sdStore.updateJob(next.id, { status: 'running', promptId, progress: null, progressLabel: null }))\n      .catch(e => sdStore.updateJob(next.id, { status: 'error', errorMessage: userMessageTransport(e) }));\n  }, [sdStore.jobs]);\n\n  useEffect(() => {\n    if (!isTauriRuntime()) return undefined;\n\n    const running = sdStore.jobs.filter(j => j.status === 'running' && j.promptId);\n    if (running.length === 0) return;\n    const interval = setInterval(async () => {\n      for (const job of running) {\n        if (polling.current.has(job.id) || finished.current.has(job.id)) continue;\n        polling.current.add(job.id);\n        try {\n          const result = await invoke('comfyui_poll_job', {\n            settings: sdStore.sdSettings,\n            promptId: job.promptId,\n          });\n          if (result.status === 'pending' || result.status === 'running') {\n            const fields = { status: 'running' };\n            if (typeof result.progress === 'number') {\n              fields.progress = result.progress;\n              fields.progressLabel = result.progressLabel || null;\n            }\n            sdStore.updateJob(job.id, fields);\n          }\n          if (result.status === 'done') {\n            finished.current.add(job.id);\n            const downloaded = await Promise.allSettled(\n              result.outputFiles.map(f =>\n                invoke('comfyui_download_output', {\n                  settings: sdStore.sdSettings,\n                  filename: f.filename,\n                  subfolder: f.subfolder,\n                  promptId: job.promptId,\n                  ...(job.mediaOutput ?? { workspaceDir }),\n                })\n              )\n            );\n            // A failed download does not cancel the other native writes. Keep\n            // the folder reservation until every output has finished.\n            const failure = downloaded.find(result => result.status === 'rejected');\n            if (failure) throw failure.reason;\n            const paths = downloaded.map(result => result.value);\n            sdStore.updateJob(job.id, { status: 'done', resultPaths: paths, progress: 1, progressLabel: '100%' });\n            for (const p of paths) onMediaCreated?.(p, job);\n          } else if (result.status === 'error') {\n            finished.current.add(job.id);\n            sdStore.updateJob(job.id, { status: 'error', errorMessage: userMessageTransport(result.error || { code: 'COMFYUI_SERVICE_ERROR', params: {} }), progress: null, progressLabel: null });\n          }\n        } catch (e) {\n          finished.current.add(job.id);\n          sdStore.updateJob(job.id, { status: 'error', errorMessage: userMessageTransport(e) });\n        } finally { polling.current.delete(job.id); }\n      }\n    }, 1500);\n    return () => clearInterval(interval);\n  }, [sdStore.jobs, workspaceDir]);\n}\n",
  "src/hooks/useXttsJobs.js": "import { userMessageTransport } from '../i18n/userMessage.js';\nimport { useEffect } from 'react';\nimport { invoke } from '@tauri-apps/api/core';\n\nexport function useXttsJobs(\n  xttsStore, onAudioGenerated, workspaceDir = null, onMediaCreated = null, onLibraryAudioReady = null,\n) {\n  useEffect(() => {\n    const isRunning = xttsStore.jobs.some(j => j.status === 'running');\n    if (isRunning) return;\n    const next = xttsStore.jobs.find(j => j.status === 'pending');\n    if (!next) return;\n    xttsStore.updateJob(next.id, { status: 'running', errorMessage: null, progress: null, progressLabel: null });\n    // Routage backend : Piper (défaut zéro-config) ou XTTS (opt-in). La file\n    // de jobs reste commune ; seule la commande Rust invoquée diffère.\n    const command = next.settings?.backend === 'piper' ? 'piper_generate_audio' : 'xtts_generate_audio';\n    invoke(command, {\n      settings: next.settings,\n      request: { ...next.request, ...(next.mediaOutput ?? { workspaceDir }) },\n    })\n      .then(async (path) => {\n        const finalPath = path;\n        xttsStore.updateJob(next.id, { status: 'done', resultPath: finalPath, progress: 1, progressLabel: '100%' });\n        onAudioGenerated(next.target, finalPath, next);\n        onMediaCreated?.(finalPath, next);\n        if (next.target?.kind === 'mediaLibrary') onLibraryAudioReady?.(finalPath, next);\n      })\n      .catch((e) => {\n        xttsStore.updateJob(next.id, { status: 'error', errorMessage: userMessageTransport(e) });\n      });\n  }, [xttsStore.jobs, workspaceDir]);\n}\n",
  "src/store/aiJobLabels.js": "function getEntryName(projectIndex, entryId, fallback) {\n  const entry = projectIndex?.entryById?.get?.(entryId);\n  const name = typeof entry?.name === 'string' ? entry.name.trim() : '';\n  return name || fallback;\n}\n\nfunction fromContextLabel(context) {\n  const label = typeof context?.targetLabel === 'string' ? context.targetLabel.trim() : '';\n  if (label) return label;\n  const regeneratedLabel = typeof context?.regenerateJob?.targetLabel === 'string'\n    ? context.regenerateJob.targetLabel.trim()\n    : '';\n  if (regeneratedLabel) return regeneratedLabel;\n  const imageLabel = typeof context?.currentImageLabel === 'string' ? context.currentImageLabel.trim() : '';\n  return imageLabel && imageLabel !== 'image actuelle' ? imageLabel : '';\n}\n\nexport function getImageJobTargetLabel(context = null, projectIndex = null) {\n  const explicitLabel = fromContextLabel(context);\n  const fieldId = typeof context?.fieldId === 'string'\n    ? context.fieldId\n    : (typeof context?.regenerateJob?.fieldId === 'string' ? context.regenerateJob.fieldId : '');\n  if (!fieldId) return explicitLabel;\n\n  if (fieldId === 'root:coverImage') return 'Menu racine - image Lunii + catalogue';\n  if (fieldId === 'root:rootImage') return 'Menu racine - image Lunii';\n  if (fieldId === 'root:thumbnailImage') return 'Menu racine - vignette catalogue';\n\n  const homeStepSuffix = ':homeStep:image';\n  if (fieldId.endsWith(homeStepSuffix)) {\n    const entryId = fieldId.slice(0, -homeStepSuffix.length);\n    return `${getEntryName(projectIndex, entryId, 'Histoire')} - image reaction Accueil`;\n  }\n\n  if (fieldId.startsWith('stage:') && fieldId.endsWith(':image')) {\n    const stageId = fieldId.slice('stage:'.length, -':image'.length);\n    return `Graphe natif - stage ${stageId || '?'}`;\n  }\n\n  const [entryId, field] = fieldId.split(':');\n  if (field === 'itemImage') {\n    return `${getEntryName(projectIndex, entryId, 'Histoire')} - image de selection`;\n  }\n  if (field === 'image') {\n    return `${getEntryName(projectIndex, entryId, 'Dossier')} - image du dossier`;\n  }\n\n  return explicitLabel || fieldId;\n}\n",
  "src/store/sdStore.js": "import { releaseProjectMediaJob } from './projectMediaOutput';\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { loadSdSettings, saveSdSettings } from './sdSettings';\nimport { KEYS, read, write } from './persistentSettings';\n\nfunction loadPersistedJobs() {\n  const jobs = read(KEYS.SD_RESULTS, { parse: JSON.parse, defaultValue: [] });\n  return Array.isArray(jobs) ? jobs : [];\n}\n\nfunction persistDoneJobs(jobs) {\n  const toSave = jobs.filter(j => j.status === 'done' && j.resultPaths.length > 0);\n  write(KEYS.SD_RESULTS, toSave, { serialize: JSON.stringify });\n}\n\nfunction genId() {\n  return Math.random().toString(36).slice(2) + Date.now().toString(36);\n}\n\n// Structure d'un job :\n// {\n//   id: string,           // uuid côté client\n//   workflowId: string,\n//   workflowName: string,\n//   status: 'pending' | 'submitting' | 'running' | 'done' | 'error',\n//   params: { positivePrompt, negativePrompt, seed, steps, cfg, loraStrength, referenceImagePath },\n//   clientId: string,\n//   promptId: string | null,\n//   resultPaths: string[],\n//   errorMessage: string | null,\n//   progress: number | null,\n//   progressLabel: string | null,\n//   targetLabel: string,\n//   createdAt: number,\n// }\n\nexport function useSdStore() {\n  const [sdSettings, setSdSettings] = useState(() => loadSdSettings());\n  const [jobs, setJobs] = useState(() => loadPersistedJobs());\n  const jobsRef = useRef(jobs);\n  const mutateJobs = useCallback((transform) => {\n    jobsRef.current = transform(jobsRef.current);\n    setJobs(jobsRef.current);\n  }, []);\n\n  const [queueOpen, setQueueOpen] = useState(false);\n\n  const updateSdSettings = useCallback((fields) => {\n    setSdSettings(prev => {\n      const next = { ...prev, ...fields };\n      saveSdSettings(next);\n      return next;\n    });\n  }, []);\n\n  const addJob = useCallback((workflowId, workflowName, params, options = {}) => {\n    const job = {\n      id: genId(),\n      workflowId,\n      workflowName,\n      status: 'pending',\n      params,\n      clientId: crypto.randomUUID?.() ?? genId(),\n      promptId: null,\n      resultPaths: [],\n      errorMessage: null,\n      progress: null,\n      progressLabel: null,\n      createdAt: Date.now(),\n      mediaOutput: options.mediaOutput,\n      projectEpoch: options.projectEpoch,\n      fieldId: options.fieldId || null,\n      targetLabel: options.targetLabel || '',\n    };\n    mutateJobs(prev => [...prev, job]);\n    return job.id;\n  }, [mutateJobs]);\n\n  const updateJob = useCallback((id, fields) => {\n    const terminal = fields.status === 'done' || fields.status === 'error';\n    const job = jobsRef.current.find((candidate) => candidate.id === id);\n    if (terminal) releaseProjectMediaJob(job);\n    mutateJobs(prev => prev.flatMap(candidate => candidate.id !== id ? [candidate]\n      : terminal && candidate.removeWhenFinished ? [] : [{ ...candidate, ...fields }]));\n  }, [mutateJobs]);\n\n  const removeJob = useCallback((id) => {\n    const job = jobsRef.current.find((candidate) => candidate.id === id);\n    if (!job) return;\n    // Keep a running producer tracked until its native write finishes.\n    const running = job.status === 'submitting' || job.status === 'running';\n    if (!running) releaseProjectMediaJob(job);\n    mutateJobs(prev => prev.flatMap(candidate => candidate.id !== id ? [candidate]\n      : running ? [{ ...candidate, removeWhenFinished: true }] : []));\n  }, [mutateJobs]);\n\n  const clearDone = useCallback(() => {\n    mutateJobs(prev => prev.filter(j => j.status !== 'done' && j.status !== 'error'));\n  }, [mutateJobs]);\n\n  const removeResult = useCallback((jobId, resultPath) => {\n    mutateJobs(prev => prev\n      .map(j => j.id === jobId ? { ...j, resultPaths: j.resultPaths.filter(p => p !== resultPath) } : j)\n      .filter(j => j.status !== 'done' || j.resultPaths.length > 0),\n    );\n  }, [mutateJobs]);\n\n  useEffect(() => {\n    persistDoneJobs(jobs);\n  }, [jobs]);\n\n  const pendingCount = jobs.filter(j => j.status === 'pending' || j.status === 'submitting' || j.status === 'running').length;\n  const hasResults = jobs.some(j => j.status === 'done' && j.resultPaths.length > 0);\n\n  return {\n    sdSettings,\n    updateSdSettings,\n    jobs,\n    addJob,\n    updateJob,\n    removeJob,\n    clearDone,\n    removeResult,\n    pendingCount,\n    hasResults,\n    queueOpen,\n    setQueueOpen,\n  };\n}\n",
  "src/store/xttsStore.js": "import { releaseProjectMediaJob } from './projectMediaOutput';\nimport { useCallback, useState, useRef } from 'react';\n\nfunction genId() {\n  return Math.random().toString(36).slice(2) + Date.now().toString(36);\n}\n\nexport function useXttsStore() {\n  const [jobs, setJobs] = useState([]);\n\n  const jobsRef = useRef(jobs);\n  const mutateJobs = useCallback((transform) => {\n    jobsRef.current = transform(jobsRef.current);\n    setJobs(jobsRef.current);\n  }, []);\n\n  const addJob = useCallback((job) => {\n    const nextJob = {\n      id: genId(),\n      kind: 'audio',\n      status: 'pending',\n      resultPath: null,\n      errorMessage: null,\n      progress: null,\n      progressLabel: null,\n      createdAt: Date.now(),\n      ...job,\n    };\n    mutateJobs(prev => [...prev, nextJob]);\n    return nextJob.id;\n  }, [mutateJobs]);\n\n  const updateJob = useCallback((id, fields) => {\n    const terminal = fields.status === 'done' || fields.status === 'error';\n    const job = jobsRef.current.find((candidate) => candidate.id === id);\n    if (terminal) releaseProjectMediaJob(job);\n    mutateJobs(prev => prev.flatMap(candidate => candidate.id !== id ? [candidate]\n      : terminal && candidate.removeWhenFinished ? [] : [{ ...candidate, ...fields }]));\n  }, [mutateJobs]);\n\n  const removeJob = useCallback((id) => {\n    const job = jobsRef.current.find((candidate) => candidate.id === id);\n    if (!job) return;\n    // Keep a running producer tracked until its native write finishes.\n    const running = job.status === 'submitting' || job.status === 'running';\n    if (!running) releaseProjectMediaJob(job);\n    mutateJobs(prev => prev.flatMap(candidate => candidate.id !== id ? [candidate]\n      : running ? [{ ...candidate, removeWhenFinished: true }] : []));\n  }, [mutateJobs]);\n\n  const clearDone = useCallback(() => {\n    mutateJobs(prev => prev.filter(job => job.status !== 'done' && job.status !== 'error'));\n  }, [mutateJobs]);\n\n  const pendingCount = jobs.filter(job =>\n    job.status === 'pending' || job.status === 'submitting' || job.status === 'running'\n  ).length;\n  const hasResults = jobs.some(job => job.status === 'done' && job.resultPath);\n\n  return {\n    jobs,\n    addJob,\n    updateJob,\n    removeJob,\n    clearDone,\n    pendingCount,\n    hasResults,\n  };\n}\n"
};
